//! Clean Up: JPEG images stored as JPEG XL and back (`jpeg_to_jxl`, `jxl_to_jpeg`). The JPEG is a q90
//! encoding of a synthetic 256 x 128 gradient made for these tests; nothing in it is third-party.

use pdfcraft_cos::{Document, ObjRef, Object};
use pdfcraft_optimize::{Compression, Report, Settings, optimize};
use std::sync::Arc;

fn pdf(image_dict: &str) -> Document {
    let mut out = b"%PDF-1.7\n1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj\n2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj\n\
3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 256 128] /Contents 4 0 R /Resources << /XObject << /Im0 5 0 R >> >> >> endobj\n\
4 0 obj << /Length 31 >> stream\nq 256 0 0 128 0 0 cm /Im0 Do Q\nendstream endobj\n"
        .to_vec();
    out.extend_from_slice(format!("5 0 obj << /Type /XObject /Subtype /Image {image_dict} /Length {} >> stream\n", JPEG.len()).as_bytes());
    out.extend_from_slice(JPEG);
    out.extend_from_slice(b"\nendstream endobj\ntrailer << /Root 1 0 R >>\n%%EOF");
    Document::open(Arc::new(out)).unwrap()
}

const GOOD: &str = "/Width 256 /Height 128 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode";

/// Only this pass runs: no resampling, no recompression, nothing else in Clean Up.
fn only(jpeg_to_jxl: bool, jxl_to_jpeg: bool) -> Settings {
    let mut s = Settings {
        jpeg_to_jxl,
        jxl_to_jpeg,
        merge_fragments: false,
        discard_thumbnails: false,
        discard_alternate_images: false,
        flate_unencoded: false,
        object_streams: false,
        lzw_to_flate: false,
        remove_invalid_links: false,
        remove_unreferenced_dests: false,
        ..Settings::default()
    };
    for images in [&mut s.color, &mut s.gray] {
        images.downsample = false;
        images.compression = Compression::Retain;
    }
    s
}

fn image(doc: &Document) -> (String, Vec<u8>) {
    let obj = doc.get(ObjRef { num: 5, generation: doc.generation(5) });
    let Object::Stream(s) = &*obj else { panic!("object 5 is not a stream") };
    (String::from_utf8_lossy(s.dict.name(b"Filter").unwrap_or(b"")).into_owned(), s.raw.to_vec())
}

fn run(doc: &mut Document, s: &Settings) -> Report {
    optimize(doc, s).unwrap()
}

#[test]
fn a_jpeg_image_is_stored_as_jpeg_xl_and_restored_byte_for_byte() {
    let mut doc = pdf(GOOD);
    let r = run(&mut doc, &only(true, false));
    assert_eq!((r.jpeg_to_jxl, r.jxl_to_jpeg), (1, 0), "{r:?}");
    let (filter, raw) = image(&doc);
    assert_eq!(filter, "JXLDecode");
    assert!(raw.len() < JPEG.len(), "{} -> {}", JPEG.len(), raw.len());

    let r = run(&mut doc, &only(false, true));
    assert_eq!((r.jpeg_to_jxl, r.jxl_to_jpeg), (0, 1), "{r:?}");
    let (filter, raw) = image(&doc);
    assert_eq!(filter, "DCTDecode");
    assert_eq!(raw, JPEG, "the original JPEG, byte for byte");
}

#[test]
fn nothing_changes_unless_asked() {
    let mut doc = pdf(GOOD);
    let r = run(&mut doc, &only(false, false));
    assert_eq!((r.jpeg_to_jxl, r.jxl_to_jpeg), (0, 0));
    assert_eq!(image(&doc), ("DCTDecode".to_string(), JPEG.to_vec()));
}

#[test]
fn images_the_conversion_cannot_keep_exactly_are_left_alone() {
    for (label, dict) in [
        ("a colour transform in the filter parameters", format!("{GOOD} /DecodeParms << /ColorTransform 0 >>")),
        ("a size that disagrees with the JPEG", GOOD.replace("/Width 256", "/Width 255")),
        ("an image mask", format!("{GOOD} /ImageMask true")),
    ] {
        let mut doc = pdf(&dict);
        let r = run(&mut doc, &only(true, false));
        assert_eq!(r.jpeg_to_jxl, 0, "{label}");
        assert_eq!(image(&doc).0, "DCTDecode", "{label}");
    }
}

#[test]
fn asking_for_both_directions_at_once_changes_nothing() {
    let mut doc = pdf(GOOD);
    let r = run(&mut doc, &only(true, true));
    assert_eq!((r.jpeg_to_jxl, r.jxl_to_jpeg), (0, 0));
    assert_eq!(image(&doc).0, "DCTDecode");
}

